// Avoid running multiple times on same element
if (element.querySelector('.pin-info-overlay')) return;

// Get description from aria-label of the first deeplink anchor or image alt
var description = '';
var links = element.querySelectorAll('a[aria-label]');
if (links.length > 0) {
  description = links[0].getAttribute('aria-label') || '';
}
if (!description) {
  var img = element.querySelector('img[alt]');
  if (img) description = img.getAttribute('alt') || '';
}
if (!description) return;

// Create container for the info text
var infoContainer = document.createElement('div');
infoContainer.className = 'pin-info-overlay';
infoContainer.style.cssText = 'padding: 8px; background: rgba(255,255,255,0.95); border-radius: 0 0 16px 16px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;';

// Create description text
var descEl = document.createElement('div');
descEl.style.cssText = 'font-size: 12px; color: #333; line-height: 1.4; margin-bottom: 4px; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;';
descEl.textContent = description;
infoContainer.appendChild(descEl);

// Insert after the image wrapper section (after first child div of pin)
var firstChild = element.firstElementChild;
if (firstChild) {
  // Find the contentLayer and insert after its parent
  var contentLayer = element.querySelector('[data-test-id="contentLayer"]');
  if (contentLayer) {
    var contentLayerParent = contentLayer.closest('.ADXRXN');
    if (contentLayerParent && contentLayerParent.parentElement) {
      contentLayerParent.parentElement.parentNode.insertBefore(infoContainer, contentLayerParent.parentElement.nextSibling);
    } else {
      firstChild.appendChild(infoContainer);
    }
  } else {
    firstChild.appendChild(infoContainer);
  }
}

